modules.type_declarations:
declare module '@1flowbase/charts' {
  import type { ComponentType, CSSProperties } from 'react';

  export type EChartPrimitive = string | number | boolean | null;
  export type EChartValue =
    | EChartPrimitive
    | readonly EChartValue[]
    | { readonly [key: string]: EChartValue | undefined };
  export type EChartOption = Readonly<Record<string, EChartValue | undefined>>;
  export interface EChartProps {
    readonly ariaLabel?: string;
    readonly className?: string;
    readonly option: EChartOption;
    readonly style?: CSSProperties;
  }
  export const EChart: ComponentType<EChartProps>;
}

declare module '@1flowbase/native-components' {
  import type {
    ComponentType,
    ElementType,
    HTMLAttributes,
    ReactNode
  } from 'react';

  export interface SurfaceProps extends HTMLAttributes<HTMLElement> {
    readonly as?: ElementType;
    readonly children?: ReactNode;
  }
  export interface ScrollableSurfaceProps extends SurfaceProps {}
  export const Surface: ComponentType<SurfaceProps>;
  export const ScrollableSurface: ComponentType<ScrollableSurfaceProps>;
}

declare module '@1flowbase/rich-text' {
  import type { ComponentType, HTMLAttributes } from 'react';

  export interface MarkdownEditorProps {
    readonly ariaLabel?: string;
    readonly className?: string;
    readonly height?: number | string;
    readonly placeholder?: string;
    readonly value: string;
    readonly onChange: (value: string) => void;
  }
  export interface MarkdownPreviewProps extends Omit<
    HTMLAttributes<HTMLDivElement>,
    'children'
  > {
    readonly value: string;
  }
  export const MarkdownEditor: ComponentType<MarkdownEditorProps>;
  export const MarkdownPreview: ComponentType<MarkdownPreviewProps>;
}
